create type public.payment_method as enum ('cash','debit','credit','transfer');
create type public.cash_session_status as enum ('open','closed');
create type public.sale_status as enum ('completed','void');
create table public.product_categories(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),name text not null check(char_length(trim(name)) between 1 and 60),position integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(business_id,name));
create table public.products(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),category_id uuid references public.product_categories(id),name text not null check(char_length(trim(name)) between 1 and 100),description text check(description is null or char_length(description)<=300),price bigint not null check(price>0),image_path text,active boolean not null default true,position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,name));
create table public.cash_sessions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),opened_by uuid not null references public.profiles(id),closed_by uuid references public.profiles(id),status public.cash_session_status not null default 'open',opening_cash bigint not null default 0 check(opening_cash>=0),counted_cash bigint check(counted_cash>=0),opening_note text,closing_note text,opened_at timestamptz not null default now(),closed_at timestamptz,check((status='open' and closed_at is null) or (status='closed' and closed_at is not null)));
create unique index one_open_cash_session_per_business on public.cash_sessions(business_id) where status='open';
create table public.sales(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),cash_session_id uuid not null references public.cash_sessions(id),sale_number bigint generated always as identity,payment_method public.payment_method not null,subtotal bigint not null check(subtotal>0),tax_amount bigint not null check(tax_amount>=0),total bigint not null check(total=subtotal+tax_amount and total>0),cash_received bigint,change_amount bigint,status public.sale_status not null default 'completed',void_reason text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),voided_at timestamptz,check((payment_method='cash' and cash_received is not null and change_amount is not null and cash_received>=total and change_amount=cash_received-total) or (payment_method<>'cash' and cash_received is null and change_amount is null)));
create table public.sale_items(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id),product_id uuid references public.products(id),product_name text not null,quantity integer not null check(quantity>0),unit_price bigint not null check(unit_price>0),line_total bigint not null check(line_total=quantity*unit_price));
create index products_business_active_idx on public.products(business_id,active,position); create index sales_session_created_idx on public.sales(cash_session_id,created_at desc); create index sale_items_sale_idx on public.sale_items(sale_id); create index sale_items_product_idx on public.sale_items(product_id);
alter table public.product_categories enable row level security; alter table public.products enable row level security; alter table public.cash_sessions enable row level security; alter table public.sales enable row level security; alter table public.sale_items enable row level security;
create policy "product category access" on public.product_categories for all to authenticated using(private.administers(business_id)) with check(private.administers(business_id));
create policy "product access" on public.products for all to authenticated using(private.administers(business_id)) with check(private.administers(business_id));
create policy "cash session access" on public.cash_sessions for all to authenticated using(private.administers(business_id)) with check(private.administers(business_id));
create policy "sale access" on public.sales for all to authenticated using(private.administers(business_id)) with check(private.administers(business_id));
create policy "sale item access" on public.sale_items for all to authenticated using(exists(select 1 from public.sales s where s.id=sale_id and private.administers(s.business_id))) with check(exists(select 1 from public.sales s where s.id=sale_id and private.administers(s.business_id)));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "product image select" on storage.objects for select to authenticated using(bucket_id='product-images' and private.administers(((storage.foldername(name))[1])::uuid)); create policy "product image insert" on storage.objects for insert to authenticated with check(bucket_id='product-images' and private.administers(((storage.foldername(name))[1])::uuid)); create policy "product image update" on storage.objects for update to authenticated using(bucket_id='product-images' and private.administers(((storage.foldername(name))[1])::uuid)); create policy "product image delete" on storage.objects for delete to authenticated using(bucket_id='product-images' and private.administers(((storage.foldername(name))[1])::uuid));
